function result=runV4R9ValidationA()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();m=jsondecode(fileread(fullfile(root,'config','paperReceiverParameterManifest_stage3s_v01.json')));p=m.parameters;p.bootstrapStepBins=.05;cases=[-366 0];records=repmat(struct('caseStartTimeSec',0,'packets',2000,'paperErrors',0,'stageErrors',0,'symbols',46000,'paperSer',0,'stageSer',0,'deltaSer',0,'lower95',0,'upper95',0),2,1);
for ci=1:2,pe=zeros(2000,1);se=zeros(2000,1);for id=1:2000,q=v4GenerateTrackAPacket(c,cases(ci),-21,id,900000000+ci*100000);paper=v4PaperNativeMidambleDecode(q,c,false);stage=v4TrackAStage55EightUpRateDecode(q,c,p);pe(id)=sum(paper.detectedPhysicalBins~=q.truth.labels);se(id)=sum(stage.detectedPhysicalBins~=q.truth.labels);if mod(id,200)==0,fprintf('R9 validation A Case %g: %d/2000\n',cases(ci),id);end,end;d=(se-pe)/23;stream=RandStream('mt19937ar','Seed',900900000+ci);draw=zeros(5000,1);for b=1:5000,idx=randi(stream,2000,2000,1);draw(b)=mean(d(idx));end;bounds=prctile(draw,[2.5 97.5]);records(ci)=struct('caseStartTimeSec',cases(ci),'packets',2000,'paperErrors',sum(pe),'stageErrors',sum(se),'symbols',46000,'paperSer',sum(pe)/46000,'stageSer',sum(se)/46000,'deltaSer',mean(d),'lower95',bounds(1),'upper95',bounds(2));end;target=all([records.stageSer]<[records.paperSer]);result=struct('status','PASS','algorithmVersion','Stage55-A-eight-up-robust-rate-v6','experimentConditionsFrozen',true,'seedDomain','r9_validation_900000000','records',records,'performanceTargetMetBothCases',target,'performanceOrderingIsAuditGate',false);folder=fullfile(root,'results','r9','validation','track_a');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,'r9_validation_a.mat'),'result','-v7.3');write(fullfile(folder,'r9_validation_a.json'),jsonencode(result,'PrettyPrint',true));
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
